mapper.select:
SELECT cm.car_id AS carId, m.maker_name AS maker, mo.model_name AS model, t.trim_name AS trim, cm.year AS year, cm.mileage AS mileage, COALESCE(MIN(pc.price), 0) AS price, COALESCE(MAX(pc.fuel), cm.fuel) AS fuel, COALESCE(MAX(pc.transmission), cm.transmission) AS transmission, COALESCE(MAX(pc.color), cm.color) AS color, COALESCE(MAX(pc.region), cm.region) AS region FROM car_master cm LEFT JOIN platform_car pc ON pc.car_id = cm.car_id LEFT JOIN cz_maker m ON m.maker_code = cm.maker_code LEFT JOIN cz_model mo ON mo.maker_code = cm.maker_code AND mo.model_group_code = cm.model_group_code AND mo.model_code = cm.model_code LEFT JOIN cz_trim t ON t.maker_code = cm.maker_code AND t.model_group_code = cm.model_group_code AND t.model_code = cm.model_code AND t.trim_code = cm.trim_code WHERE cm.adv_status IN ('ONSALE', 'ADVERTISE')
AND cm.model_code IN #{code}
GROUP BY cm.car_id, m.maker_name, mo.model_name, t.trim_name, cm.year, cm.mileage, cm.fuel, cm.transmission, cm.color, cm.region ORDER BY cm.car_id LIMIT #{limit}

SELECT trim_code AS code, trim_name AS name
FROM cz_trim
WHERE MAKER_CODE = #{makerCode}
  AND model_group_code = #{modelGroupCode}
  AND MODEL_CODE = #{modelCode}
ORDER BY name

SELECT grade_code AS code, grade_name AS name
FROM cz_grade
WHERE MAKER_CODE = #{makerCode}
  AND model_group_code = #{modelGroupCode}
  AND MODEL_CODE = #{modelCode}
  AND TRIM_CODE = #{trimCode}
ORDER BY name

SELECT cm.car_id AS carId, cm.maker_code AS makerCode, cm.model_group_code AS modelGroupCode, cm.model_code AS modelCode, cm.trim_code AS trimCode, cm.grade_code AS gradeCode, COALESCE(NULLIF(TRIM(MAX(m.maker_name)), ''), NULLIF(TRIM(MAX(pc.maker_name)), '')) AS makerName, COALESCE(NULLIF(TRIM(MAX(mg.model_group_name)), ''), NULLIF(TRIM(MAX(pc.model_group_name)), '')) AS modelGroupName, COALESCE(NULLIF(TRIM(MAX(mo.model_name)), ''), NULLIF(TRIM(MAX(pc.model_name)), '')) AS modelName, COALESCE(NULLIF(TRIM(MAX(t.trim_name)), ''), NULLIF(TRIM(MAX(pc.trim_name)), '')) AS trimName, cm.year AS year, cm.mileage AS km, MIN(pc.price) AS priceMin, MAX(pc.price) AS priceMax, MAX(pc.updated_at) AS priceUpdatedAt, COUNT(DISTINCT pc.platform_name) AS platformCount, COALESCE(MAX(pc.fuel), cm.fuel) AS fuel, COALESCE(MAX(pc.transmission), cm.transmission) AS transmission, COALESCE(MAX(pc.color), cm.color) AS color, COALESCE(MAX(pc.body_type), cm.body_type) AS bodyType, COALESCE(MAX(pc.region), cm.region) AS region, COALESCE(MAX(pc.option_array), '') AS optionArray, COALESCE(MAX(pc.sel_option_array), '') AS selOptionArray, cm.car_no AS carNo, MAX(img.representativeImageUrl) AS representativeImageUrl FROM car_master cm LEFT JOIN platform_car pc ON pc.car_id = cm.car_id LEFT JOIN cz_maker m ON m.maker_code = cm.maker_code LEFT JOIN cz_model_group mg ON mg.maker_code = cm.maker_code AND mg.model_group_code = cm.model_group_code LEFT JOIN cz_model mo ON mo.maker_code = cm.maker_code AND mo.model_group_code = cm.model_group_code AND mo.model_code = cm.model_code LEFT JOIN cz_trim t ON t.maker_code = cm.maker_code AND t.model_group_code = cm.model_group_code AND t.model_code = cm.model_code AND t.trim_code = cm.trim_code LEFT JOIN ( SELECT car_id, car_image_url AS representativeImageUrl FROM ( SELECT pc2.car_id, pc2.car_image_url, ROW_NUMBER() OVER (PARTITION BY pc2.car_id ORDER BY COALESCE(pp.priority, 999) ASC) rn FROM platform_car pc2 LEFT JOIN cz_platform_priority pp ON pp.platform_name = pc2.platform_name WHERE pc2.car_image_url IS NOT NULL AND TRIM(IFNULL(pc2.car_image_url,'')) != '' ) x WHERE rn = 1 ) img ON img.car_id = cm.car_id WHERE cm.car_id IN
#{id}
GROUP BY cm.car_id, cm.maker_code, cm.model_group_code, cm.model_code, cm.trim_code, cm.grade_code, cm.year, cm.mileage, cm.fuel, cm.transmission, cm.color, cm.body_type, cm.region, cm.car_no, m.maker_name, mo.model_name, t.trim_name
